 <aside><section className="panel weather"><div className="section-row"><h2><CloudSun size={21}/>{t('Ride-day weather','라이딩 당일 날씨')}</h2><button className="icon-button" aria-label={t('Refresh weather','날씨 새로고침')} onClick={()=>setWReload(v=>v+1)}><RefreshCw size={16}/></button></div>{!weather?<p className="muted">{t('Checking forecast…','예보 확인 중…')}</p>:weather.status==='available'?<><p className="small muted">{t('°C · km/h · Korean time','°C · km/h · 한국 시간')}</p>{weather.locations.map((l:any)=><div className="weather-location" key={l.name}><h3>{l.name}</h3><div className="weather-hours">{l.hours.map((h:any)=><div key={h.hour}><small>{h.hour}:00</small><strong>{Math.round(h.temp)}°</strong><span>{h.rain}% ☂</span><span><Wind size={13}/>{Math.round(h.wind)}</span><small>{t('Gust','돌풍')} {Math.round(h.gust)}</small></div>)}</div><p className="small muted">{t('Sunset','일몰')} {l.sunset.slice(11,16)}</p></div>)}<p className="small muted">{t('Updated','업데이트')} {new Date(weather.updatedAt).toLocaleString(ko?'ko-KR':'en-US',{timeZone:'Asia/Seoul'})}</p></>:<div className="weather-empty"><CloudSun size={45}/><h3>{weather.status==='outside'?t('A little early for a forecast','아직 예보 기간 전입니다'):weather.status==='past'?t('Ride date has passed','지난 라이딩 일정입니다'):t('Weather unavailable','날씨를 불러올 수 없습니다')}</h3><p>{weather.status==='outside'?t('Your actual ride-date forecast will appear here when it becomes available.','실제 라이딩 날짜의 예보가 제공되면 여기에 표시됩니다.'):t('Try refreshing for the latest information.','새로고침하여 다시 확인하세요.')}</p>{weather.status==='outside'&&<span className="badge">{t('From','예보 시작')} {weather.availableFrom}</span>}</div>}<a className="source" href="https://open-meteo.com/" target="_blank" rel="noreferrer">Open-Meteo ↗</a></section>
