const edges=new Map<string,{to:string;leg:Leg}[]>();
function edge(a:string,b:string,leg:Leg){edges.set(a,[...(edges.get(a)||[]),{to:b,leg}]);edges.set(b,[...(edges.get(b)||[]),{to:a,leg}]);}
for(const chain of chains) chain.kms.forEach((km,i)=>edge(chain.ids[i],chain.ids[i+1],{km,kind:km===null?'missing':'published',source:chain.source}));
