export function between(a:string,b:string):{stops:string[];legs:Leg[]}{
 if(a===b)return {stops:[a],legs:[]};
 // Prefer a documented route within a corridor; no straight-line distance enters this graph.
 const same=chains.find(c=>c.ids.includes(a)&&c.ids.includes(b));
 if(same){const i=same.ids.indexOf(a),j=same.ids.indexOf(b);const ids=same.ids.slice(Math.min(i,j),Math.max(i,j)+1);if(i>j)ids.reverse();return {stops:ids,legs:ids.slice(1).map((id,k)=>edges.get(ids[k])!.find(e=>e.to===id)!.leg)};}
 const queue:[string,string[],Leg[]][]=[[a,[a],[]]],seen=new Set([a]);
 while(queue.length){const [at,path,legs]=queue.shift()!;for(const e of edges.get(at)||[]){if(seen.has(e.to))continue;const next=[...path,e.to],nl=[...legs,e.leg];if(e.to===b)return {stops:next,legs:nl};seen.add(e.to);queue.push([e.to,next,nl]);}}
 return {stops:[a,b],legs:[{km:null,kind:'missing'}]};
}
export function makeDay(date:string,waypoints:string[],id:string=crypto.randomUUID()):RideDay{
 const stops=[waypoints[0]],legs:Leg[]=[];
 for(let i=1;i<waypoints.length;i++){const part=between(waypoints[i-1],waypoints[i]);stops.push(...part.stops.slice(1));legs.push(...part.legs);}
 return {id,date,stops,legs,note:''};
}
export function total(legs:Leg[]):number|null{return legs.some(l=>l.km===null)?null:Math.round(legs.reduce((n,l)=>n+l.km!,0)*10)/10;}
export function remaining(day:RideDay,index:number){return total(day.legs.slice(Math.max(0,index)));}
export function koreaToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
export function plusDay(date:string){return new Date(Date.parse(date)+86400000).toISOString().slice(0,10);}
