export function weatherArea(id:string){const direct=coastalAreas[id];if(direct)return {point:[direct[0],direct[1]],name:direct[2]};const c=cp(id),r=routes.find(x=>x.name===c?.route);return {point:r?.point||[37.5665,126.978],name:r?`${r.name} · ${r.ko}`:'Seoul · 서울'};}
export function dayArea(d:RideDay,where:number){return d.stops.length?weatherArea(d.stops[Math.min(d.stops.length-1,Math.max(0,where))]):{point:d.point||[37.5665,126.978],name:d.area||'Seoul · 서울'};}
export function dayName(d:RideDay,ko=false){if(d.title)return ko?(d.titleKo||d.title):d.title;return d.stops.length?[cp(d.stops[0]),cp(d.stops[d.stops.length-1])].map(c=>ko?c.ko:c.name).join(' → '):'';}
export function validTrip(v:unknown):v is RideTrip{
 const t=v as RideTrip;if(!t||typeof t.id!=='string'||!/^[a-zA-Z0-9_-]{1,80}$/.test(t.id)||typeof t.name!=='string'||t.name.length>120||!Array.isArray(t.days)||!t.days.length||t.days.length>40)return false;
