import {koreaToday} from './ride-model';
export type Forecast={status:'available'|'outside'|'past'|'error';hours?:{time:string;rain:number|null;mm:number|null}[];updatedAt?:string;availableFrom?:string};
export async function forecast(date:string,point:number[],signal:AbortSignal):Promise<Forecast>{
 const ahead=Math.round((Date.parse(date)-Date.parse(koreaToday()))/86400000);
 if(ahead<0)return {status:'past'};
 if(ahead>15)return {status:'outside',availableFrom:new Date(Date.parse(date)-15*86400000).toISOString().slice(0,10)};
 const u=new URL('https://api.open-meteo.com/v1/forecast');
 Object.entries({latitude:String(point[0]),longitude:String(point[1]),hourly:'precipitation_probability,precipitation',timezone:'Asia/Seoul',start_date:date,end_date:date}).forEach(([k,v])=>u.searchParams.set(k,v));
 try{const r=await fetch(u,{signal});if(!r.ok)throw Error('Forecast unavailable');const j:any=await r.json();if(!Array.isArray(j.hourly?.time)||j.hourly.time.length<20)throw Error('Incomplete forecast');return {status:'available',updatedAt:new Date().toISOString(),hours:j.hourly.time.map((time:string,i:number)=>({time:time.slice(11,16),rain:Number.isFinite(j.hourly.precipitation_probability?.[i])?j.hourly.precipitation_probability[i]:null,mm:Number.isFinite(j.hourly.precipitation?.[i])?j.hourly.precipitation[i]:null}))};}catch(e){if(signal.aborted)throw e;return {status:'error'};}
}
// NOAA General Solar Position Calculations. Zenith: 90.833° sunrise, 102° nautical twilight.
// Regional approximation in KST; independent of weather availability.
export function daylight(date:string,point:number[]){
 const d=new Date(date+'T12:00:00Z'),year=d.getUTCFullYear(),days=(Date.UTC(year+1,0,1)-Date.UTC(year,0,1))/86400000;
 const day=(Date.UTC(year,d.getUTCMonth(),d.getUTCDate())-Date.UTC(year,0,1))/86400000;
 const g=2*Math.PI/days*day,rad=Math.PI/180;
 const eq=229.18*(.000075+.001868*Math.cos(g)-.032077*Math.sin(g)-.014615*Math.cos(2*g)-.040849*Math.sin(2*g));
 const dec=.006918-.399912*Math.cos(g)+.070257*Math.sin(g)-.006758*Math.cos(2*g)+.000907*Math.sin(2*g)-.002697*Math.cos(3*g)+.00148*Math.sin(3*g);
 const noon=720-4*point[1]-eq+540,lat=point[0]*rad;
 const offset=(zenith:number)=>4*Math.acos(Math.cos(zenith*rad)/(Math.cos(lat)*Math.cos(dec))-Math.tan(lat)*Math.tan(dec))/rad;
 const time=(minutes:number)=>{if(!Number.isFinite(minutes))return '—';const n=(Math.round(minutes)+1440)%1440;return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;};
 return {bmnt:time(noon-offset(102)),sunrise:time(noon-offset(90.833)),sunset:time(noon+offset(90.833)),eent:time(noon+offset(102))};
}

